from zoneinfo import ZoneInfo
from datetime import datetime, timedelta, time

CAP_EVENTS, CAP_TOK, BUDGET = 60, 400, 8000
SCORE = {'work_tool': 3, 'long_session': 2}

def window(day, tz):
    z = ZoneInfo(tz)
    start = datetime.combine(day, time(0), z)
    end = datetime.combine(day + timedelta(days=1), time(0), z)  # local midnight, so DST days are 23 or 25 h
    return start.astimezone(ZoneInfo('UTC')), end.astimezone(ZoneInfo('UTC'))

def collect(owner_id, day, tz, scope_client, tok_len):
    start, end = window(day, tz)
    seen, events, cursor = set(), [], None
    while True:
        page = scope_client.search(owner=owner_id, zone='personal', start=start, end=end, cursor=cursor)
        for e in page.rows:
            if e.owner_id != owner_id:  # second check, fail closed
                raise PermissionError('foreign row')
            if e.event_id not in seen:
                seen.add(e.event_id); events.append(e)
        cursor = page.next
        if not cursor: break
    ranked = sorted(events, key=lambda e: (-SCORE.get(e.kind, 1), e.started_at))[:CAP_EVENTS]
    kept, used = [], 0
    for e in ranked:
        t = min(tok_len(e.summary), CAP_TOK)
        if used + t > BUDGET: break
        kept.append(e); used += t
    kept.sort(key=lambda e: e.started_at)
    return kept, len(events) - len(kept)

