import hashlib, json

def item_hash(i):
    body = {k: i[k] for k in ('tool', 'issue', 'change_type', 'change_text')}
    return hashlib.sha256(json.dumps(body, sort_keys=True, separators=(',', ':')).encode()).hexdigest()

def submit(db, policy, item):
    h = item_hash(item)
    try:
        verdict = policy.check(owner=item['owner_id'], tool=item['tool'],
                               issue=item['issue'], change_type=item['change_type'])  # 2 s, 2 retries
    except TimeoutError:
        verdict = 'force_manual'  # fail closed: never auto when policy is silent
    if verdict == 'deny':
        return save(db, item, h, 'rejected', None)
    auto = (verdict == 'allow' and item['guard_verdict'] == 'clean'
            and db.exists('agent_auto', owner_id=item['owner_id'], tool=item['tool']))
    return save(db, item, h, 'approved' if auto else 'pending', 'auto' if auto else None)

def decide(db, item_id, decision, seen_hash, session_owner):
    row = db.get('agent_item', item_id)
    if row.owner_id != session_owner:  # only the owner can decide
        raise PermissionError
    if row.state != 'pending' or row.item_hash != seen_hash:  # stale approval is void
        raise ValueError('stale')
    db.update('agent_item', item_id, state='approved' if decision == 'approve' else 'rejected', mode='manual')

