import hashlib, time

def idem_key(i):
    return hashlib.sha256(f"{i.owner_id}|{i.tool}|{i.issue}|{i.item_hash}".encode()).hexdigest()

def write_item(db, vault, egress, adapter, i):
    if hash_of(i) != i.item_hash:
        return Result('failed', reason='hash_mismatch')  # text changed after approval
    if not egress.allows(adapter.host):
        return Result('failed', reason='egress_denied')
    k = idem_key(i)
    if not db.reserve(k, i):  # INSERT ... ON CONFLICT DO NOTHING, rowcount 0 means a prior attempt
        prior = db.get(k)
        return resolve(prior, adapter, vault, i)  # read back if state is sent or reserved
    token = vault.token_for(owner=i.owner_id, tool=i.tool)  # owner's own grant, never admin
    for n in range(3):
        try:
            r = adapter.post(token, i, key=k, timeout=10)
            if r.status == 429:
                time.sleep(float(r.headers.get('Retry-After', 2 ** n))); continue
            db.set(k, 'confirmed', r.id); return Result('done', r.id)
        except TimeoutError:
            db.set(k, 'sent')
            if adapter.applied(token, i, k):  # read back before any retry
                db.set(k, 'confirmed'); return Result('done')
    db.set(k, 'failed'); return Result('failed')

