import re, hashlib

N = 8

def norm(t):
    return re.sub(r'\s+', ' ', re.sub(r'[^a-z0-9 ]', ' ', t.lower())).strip()

def shingles(t, n=N):
    w = norm(t).split()
    return {hashlib.blake2b(' '.join(w[i:i+n]).encode(), digest_size=8).digest()
            for i in range(len(w) - n + 1)}

def overlap(text, priv_sh, priv_norm):
    sh = shingles(text)
    m = len(sh & priv_sh)
    t = norm(text)
    # second check: any 20-character exact run, which catches short private messages
    if any(t[i:i+20] in priv_norm for i in range(max(0, len(t) - 19))):
        m = max(m, 1)
    return m / max(len(sh), 1), m

def check(item, private_text, confirmed=False):
    if not private_text:
        return blocked(item, 'source_missing')  # fail closed
    p_norm = norm(private_text)
    p_sh = shingles(private_text)
    score, m = overlap(item.change_text, p_sh, p_norm)
    if m == 0:
        return Checked(item.item_id, item.change_text, 'clean', 0.0)
    if confirmed:
        return Checked(item.item_id, item.change_text, 'owner_confirmed', score)
    s2, m2 = overlap(item.safe_text, p_sh, p_norm)
    if m2 == 0 and item.safe_text:
        return Checked(item.item_id, item.safe_text, 'paraphrased', score)
    return blocked(item, 'copied_private_text')
